function operationTile(id,icon,tone){const b=node("button","","operation-tile tone-"+tone);b.type="button";b.dataset.operation=id;b.setAttribute("aria-pressed",String(val("action")===id));const mark=node("span","","choice-icon");mark.append(glyph(icon));b.append(mark,node("span",actions[id]));b.addEventListener("click",()=>{if($("operationDialog").open)$("operationDialog").close();$("editor").hidden=false;$("reopenEditor").hidden=true;$("action").value=id;$("message").textContent="";fields();$("editorTitle").focus({preventScroll:true});$("editor").scrollIntoView({block:"start"});});return b;}
function syncOperations(){const active=val("action"),allowed=new Set(Array.from($("action").options,o=>o.value));$("actionShortcuts").replaceChildren();$("operationGroups").replaceChildren();for(const id of quickActions[section]??[]){if(allowed.has(id)){const group=operationGroups.find(g=>g[3].includes(id));$("actionShortcuts").append(operationTile(id,group[1],group[2]));}}for(const [name,icon,tone,ids] of operationGroups){const items=ids.filter(id=>allowed.has(id));if(!items.length)continue;const box=node("section","","operation-group");box.append(node("h3",name));const grid=node("div","","operation-grid");for(const id of items)grid.append(operationTile(id,icon,tone));box.append(grid);$("operationGroups").append(box);}const incoming=val("direction")==="in";$("editorTitle").textContent=active==="record"?(incoming?"دخل جديد":"مصروف جديد"):actions[active]??"العمليات";$("submitOperation").textContent=active==="record"?(incoming?"حفظ الدخل":"حفظ المصروف"):active==="edit"?"حفظ التعديل":"تنفيذ العملية";$("openOperations").textContent="جميع العمليات";$("editorTitle").tabIndex=-1;}
