function openEntry(action,direction,editId=null){const origin={section,focusId:action==="record"?(direction==="in"?"quickIncome":"quickExpense"):(document.activeElement?.id||"quickExpense")};showMore(false);$("entryNotice").hidden=true;$("message").textContent="";section=action==="settle"?"schedule":action==="contribution"?"plan":"cash";selectOpts($("action"),sections[section][1].map(x=>[x,actions[x]]));$("editor").hidden=false;$("action").value=action;fields();if(action==="record"){$("direction").value=direction;$("direction").dispatchEvent(new Event("change"));if(direction==="in"&&Array.from($("incomeSource").options).some(o=>o.value==="salary")){$("incomeSource").value="salary";choiceSync($("incomeSource"));}$("amt").value="";$("date").value=localDate(new Date());}else if(editId){$("target").value=editId;$("target").dispatchEvent(new Event("change"));}entryOrigin=origin;$("operationTools").hidden=true;if($("direction"))$("direction").parentElement.hidden=action==="record";$("entryDialog").append($("editor"));if(origin.section==="overview"){for(const b of [...$("nav").children,...$("moreNav").children]){if(b.dataset.section==="overview")b.setAttribute("aria-current","page");else b.removeAttribute("aria-current");}}$("entryDialog").dataset.entryKind=action==="record"?direction:action;if(action==="record"&&direction==="in"){const grid=$("incomeSourceChoices"),blank=Array.from(grid.children).find(b=>b.dataset.choice==="");if(blank)grid.append(blank);}$("entryDialog").showModal();$("entryDialog").scrollTop=0;$("amt").focus({preventScroll:true});}
