function choiceField(id,label,opts){const wrapper=node("div","","choice-field"),heading=node("span",label,"choice-label"),x=node("select"),grid=node("div","","choice-grid");x.id=id;x.hidden=true;x.setAttribute("aria-label",label);selectOpts(x,opts);grid.id=id+"Choices";grid.setAttribute("role","group");grid.setAttribute("aria-label",label);for(const [value,name] of opts){const b=node("button","","choice-chip tone-"+(toneByCategory[value]??"slate"));b.type="button";b.dataset.choice=value;b.setAttribute("aria-pressed",String(x.value===value));const mark=node("span","","choice-icon");mark.append(glyph(iconByChoice[value]??"tag"));b.append(mark,node("span",name));b.addEventListener("click",()=>{x.value=value;x.dispatchEvent(new Event("change"));});grid.append(b);}x.addEventListener("change",()=>choiceSync(x));wrapper.append(heading,x,grid);$("fields").append(wrapper);}
